// Se envian las columnas tal cual; el backend las mapea. Aqui no se calcula nada clinico.
const fila = { ...$json };
const rowNumber = fila.row_number;
delete fila.row_number;
const marca = fila['Marca temporal'] || fila['Timestamp'] || '';
if (!marca && !rowNumber) {
  throw new Error('Fila sin Marca temporal ni numero de fila: no se puede identificar la respuesta');
}
const id = `forms|${rowNumber ?? ''}|${marca}`.slice(0, 120);
return { json: { id_respuesta: id, campos: fila } };

// Solo conteos y numero de lote: nunca nombres, CURP ni datos de salud.
const j = $input.first().json;
return [{ json: {
  asunto: `Alta automatica desde Forms: ${j.erroneos} con error, ${j.por_revisar} por revisar`,
  detalle: `Lote ${j.lote_id}. Procesadas correctamente: ${j.exitosos}. Revisar en LabResultados > Lotes.`
} }];

// Sin datos del payload: solo identificadores de la ejecucion y el mensaje de error truncado.
const j = $input.first().json;
const msg = String((j.execution && j.execution.error && j.execution.error.message) || '').slice(0, 200);
return [{ json: {
  asunto: `Fallo en ${j.workflow && j.workflow.name}`,
  detalle: `Ejecucion ${j.execution && j.execution.id}, nodo: ${j.execution && j.execution.lastNodeExecuted}. ${msg}`
} }];
